const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args && typeof source.args === 'object' ? source.args : {};
const rawTool = String(source.tool || args.tool || '').trim();
const tool = rawTool.replace(/^media\./, '');
const fileId = String(args.fileId || args.telegramFileId || source.fileId || '').trim();
const fileName = String(args.fileName || source.fileName || '').trim();
const mimeType = String(args.mimeType || source.mimeType || '').trim();
const attachmentKind = String(args.attachmentKind || source.attachmentKind || '').trim();
const hasAttachment = Boolean(args.hasAttachment ?? source.hasAttachment ?? fileId);
const text = String(args.text || args.instruction || source.text || source.rawText || '').trim();
const question = String(args.question || text).trim();
const prompt = String(args.prompt || text).trim();
const language = String(args.language || '').trim();
const voice = String(args.voice || '').trim();
const model = String(args.model || '').trim();
const responseMode = String(args.responseMode || 'json').trim();
const coreToken = String($env.MIA_CORE_API_TOKEN || '').trim();

const toolToEndpoint = {
  'image_ocr': '/mia/media/image/ocr',
  'image_describe': '/mia/media/image/describe',
  'image_extract_fields': '/mia/media/image/extract-fields',
  'document_extract_text': '/mia/media/document/extract-text',
  'document_summarize': '/mia/media/document/summarize',
  'document_search_answer': '/mia/media/document/search-answer',
  'document_extract_fields': '/mia/media/document/extract-fields',
  'audio_transcribe': '/mia/media/audio/transcribe',
  'audio_summarize': '/mia/media/audio/summarize',
  'video_transcribe': '/mia/media/video/transcribe',
  'video_summarize': '/mia/media/video/summarize',
  'tts_speak': '/mia/media/tts/speak',
};

const configuredCoreUrl = String($env.MIA_CORE_URL || 'http://mia-core:8000').replace(/\/$/, '');
const coreBaseUrl = configuredCoreUrl.replace(/\/mia\/chat\/?$/, '');
const endpointPath = toolToEndpoint[tool] || '';
if (!endpointPath) {
  return [{ json: { ok: false, error: `Unsupported media tool: ${rawTool || tool}`, tool: rawTool || tool } }];
}

const needsFile = tool !== 'tts_speak';
return [{
  json: {
    ok: true,
    tool,
    rawTool,
    endpointPath,
    coreBaseUrl,
    coreUrl: `${coreBaseUrl}${endpointPath}`,
    coreToken,
    fileId,
    fileName,
    mimeType,
    attachmentKind: attachmentKind || (tool.startsWith('video_') ? 'video' : tool.startsWith('audio_') ? 'audio' : tool.startsWith('document_') ? 'document' : 'photo'),
    hasAttachment,
    text,
    question,
    prompt,
    language,
    voice,
    model,
    responseMode,
    needsFile,
    requestId: String(source.requestId || '').trim(),
    originChatId: String(source.originChatId || source.chatId || '').trim(),
    deliveryMode: String(source.deliveryMode || 'return').trim() || 'return',
  }
}];

const input = $('Normalize Media Input').item.json || {};
const filePath = String($json.result?.file_path || '').trim();
if (!filePath) {
  return [{ json: { ok: false, error: 'Telegram file path not found.', ...input } }];
}
return [{
  json: {
    ...input,
    filePath,
    downloadUrl: `https://api.telegram.org/file/bot${$env.TELEGRAM_BOT_TOKEN}/${filePath}`,
  }
}];

const input = $('Prepare Download').item.json || {};
const binaryMeta = $input.item.binary?.data || $binary?.data || null;
if (!binaryMeta) {
  return [{ json: { ...input, ok: false, error: 'No binary data downloaded from Telegram.' } }];
}
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const binary = buffer.toString('base64');
const payload = {
  tool: input.tool,
  request_id: input.requestId,
  chat_id: input.originChatId,
  text: input.text,
  question: input.question,
  prompt: input.prompt,
  file_base64: binary,
  file_name: input.fileName || binaryMeta.fileName || 'attachment.bin',
  mime_type: input.mimeType || binaryMeta.mimeType || 'application/octet-stream',
  attachment_kind: input.attachmentKind,
  has_attachment: Boolean(input.hasAttachment),
  language: input.language,
  voice: input.voice,
  model: input.model,
  response_mode: input.responseMode,
};
return [{
  json: {
    ...input,
    ok: true,
    corePayload: payload,
    coreUrl: input.coreUrl || `${input.coreBaseUrl}${input.endpointPath}`,
  }
}];

const source = $('Normalize Media Input').item.json || {};
const output = $json || {};
const text = String(output.text || output.summary || output.result?.text || output.result?.summary || output.result?.answer || output.result?.ocr_text || '').trim() || 'Mia đã xử lý xong file media này.';
return [{
  json: {
    ok: output.ok !== false,
    tool: output.tool || source.tool || '',
    text,
    result: output.data || output.result || output,
    audioBase64: output.audio_base64 || output.audioBase64 || '',
    links: Array.isArray(output.links) ? output.links : [],
    requestId: source.requestId || '',
    originChatId: source.originChatId || '',
    deliveryMode: source.deliveryMode || 'return',
  }
}];

const source = $('Normalize Media Input').item.json || {};
const output = $json || {};
const deliveryMode = source.deliveryMode || 'return';
const text = String(output.text || source.text || 'Mia đã chuẩn bị phần đọc giọng nói.').trim();
return [{
  json: {
    ok: output.ok !== false,
    tool: output.tool || source.tool || 'tts_speak',
    text,
    audioBase64: output.audio_base64 || output.audioBase64 || '',
    mimeType: output.mime_type || output.mimeType || 'audio/mpeg',
    fileName: output.file_name || output.fileName || 'mia-tts.mp3',
    requestId: source.requestId || '',
    originChatId: source.originChatId || '',
    deliveryMode,
    shouldSendTelegram: deliveryMode === 'telegram',
  }
}];

const input = $('Normalize TTS Result').item.json || $json || {};
const audioBase64 = String(input.audioBase64 || '').trim();
if (!audioBase64) {
  return [{ json: { ok: false, error: 'No audio payload returned from TTS core.', ...input } }];
}
const buffer = Buffer.from(audioBase64, 'base64');
const binaryData = await this.helpers.prepareBinaryData(buffer, input.fileName || 'mia-tts.mp3', input.mimeType || 'audio/mpeg');
return [{
  json: {
    ...input,
    ok: true,
  },
  binary: {
    data: binaryData,
  },
}];

const source = $json || {};
return [{
  json: {
    ok: source.ok !== false,
    tool: source.tool || 'tts_speak',
    text: source.text || 'Mia đã chuẩn bị câu trả lời bằng giọng nói.',
    audioBase64: source.audioBase64 || '',
    mimeType: source.mimeType || 'audio/mpeg',
    fileName: source.fileName || 'mia-tts.mp3',
    requestId: source.requestId || '',
    originChatId: source.originChatId || '',
    deliveryMode: source.deliveryMode || 'return',
  }
}];
